1	// Command ledger 是本地器具校准台账的命令行入口。
2	//
3	// 用法：
4	//
5	//	ledger -f 台账文件.json <子命令> [参数]
6	//
7	// 数据只保存在 -f 指定的本机文件中；不指定时使用当前目录下的 ledger.json。
8	// 不同文件是互不混入的不同台账，退出后再次打开同一文件可继续查询和操作。
9	package main
10	
11	import (
12		"encoding/json"
13		"errors"
14		"flag"
15		"fmt"
16		"io"
17		"math"
18		"os"
19		"strconv"
20		"strings"
21	
22		"github.com/bengzyyys/calibration-ledger/calibrate"
23	)
24	
25	const usageText = `本地器具校准台账（仅本机，不连接真实实验室）
26	
27	用法：
28	  ledger -f <台账文件> [--json] <子命令> [参数]
29	
30	子命令：
31	  register   登记器具：--id 编号 --name 名称 --allowed 允许绝对误差
32	  status     切换状态：--id 编号 --status 在用|停用|待校准
33	  cert       录入证书：--instrument 器具编号 --number 证书编号 \
34	             --cal-date YYYY-MM-DD --expiry YYYY-MM-DD \
35	             --method 方法 --error 测得误差 --summary 摘要
36	  use        申请使用器具：--id 编号（允许与拒绝都会留痕）
37	  review     按器具核对：--id 编号
38	  list       列出全部登记器具
39	  plan       建立校准计划：--instrument 器具编号 --number 计划编号 \
40	             --date YYYY-MM-DD --note 非空说明
41	  reschedule 计划改期：--number 计划编号 --date 新日期 --reason 非空原因
42	  cancel     取消计划：--number 计划编号 --reason 非空原因
43	  complete   用证书完成计划：--number 计划编号 --certificate 证书编号
44	  todos      校准待办：[--instrument 器具编号]（默认全部未结束计划）
45	
46	通用参数：
47	  -f, --file   台账文件路径（默认 ledger.json）
48	      --json   以 JSON 输出结果
49	
50	退出码：0 成功；1 业务拒绝或未找到；2 参数或读写错误。
51	`
52	
53	// options 是所有子命令共用的全局参数。
54	type options struct {
55		file   string
56		asJSON bool
57	}
58	
59	func main() {
60		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
61	}
62	
63	func run(args []string, stdout, stderr io.Writer) int {
64		if len(args) == 0 {
65			fmt.Fprint(stderr, usageText)
66			return 2
67		}
68		var opts options
69		fileSet := false
70		cmd := ""
71		businessArgs := make([]string, 0, len(args))
72		// 全局参数（-f/--file、--json）既可以写在子命令前，也可以与器具编号、
73		// 证书编号等业务参数交错写在子命令之后。这里先从左到右扫描整条命令行，
74		// 剥除全局参数并确定最终台账路径，再打开该文件：因此 -f 出现的位置不会
75		// 改变它选中的台账；同一次调用出现多个文件参数时，短名与长名共同参与
76		// 从左到右的顺序，以最后一次明确给出的路径为准。
77		// 子命令的业务标志（--method、--summary 等）都需要值：不带等号时紧跟的
78		// 下一个参数就是它的值。值必须原样保留为字段内容——即使它看起来是
79		// -f、--file=…、-f… 或 --json，也不参与台账选择与输出格式设置；
80		// 只有出现在完整字段之外（或子命令之前）的同名写法才是全局参数。
81		for i := 0; i < len(args); i++ {
82			a := args[i]
83			if cmd == "" && !strings.HasPrefix(a, "-") {
84				// 第一个不以“-”开头的参数是子命令；其后的位置参数仍要继续扫描。
85				cmd = a
86				continue
87			}
88			switch {
89			case a == "-f" || a == "--file" || a == "-file":
90				if i+1 >= len(args) {
91					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
92					return 2
93				}
94				i++
95				opts.file = args[i]
96				fileSet = true
97			case strings.HasPrefix(a, "--file="):
98				opts.file = a[len("--file="):]
99				fileSet = true
100			case strings.HasPrefix(a, "-file="):
101				opts.file = a[len("-file="):]
102				fileSet = true
103			case strings.HasPrefix(a, "-f="):
104				opts.file = strings.TrimPrefix(a, "-f=")
105				fileSet = true
106			case strings.HasPrefix(a, "-f") && len(a) > 2:
107				opts.file = a[2:]
108				fileSet = true
109			case a == "--json" || a == "-json":
110				opts.asJSON = true
111			case a == "--" && cmd != "":
112				// “--” 终止后续标志解析：其后的参数原样交给子命令
113				// （与此前 flag 包的行为一致），即使其中出现 -f 也不再视为全局参数。
114				businessArgs = append(businessArgs, args[i:]...)
115				i = len(args)
116			default:
117				if cmd == "" {
118					fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
119					return 2
120				}
121				businessArgs = append(businessArgs, a)
122				// 业务标志不带等号时，下一个参数是它的字段值：原样一并转交子命令，
123				// 绝不再按全局参数解释（与 flag 包对字符串标志的取值行为一致）。
124				// 值缺失时不在这里补，由子命令解析时报“标志需要值”。
125				if strings.HasPrefix(a, "-") && !strings.Contains(a, "=") && i+1 < len(args) {
126					i++
127					businessArgs = append(businessArgs, args[i])
128				}
129			}
130		}
131		if fileSet {
132			if strings.TrimSpace(opts.file) == "" {
133				fmt.Fprintln(stderr, "台账文件路径不能为空或只有空白")
134				return 2
135			}
136		} else {
137			opts.file = "ledger.json"
138		}
139		if cmd == "" {
140			fmt.Fprint(stderr, usageText)
141			return 2
142		}
143		cmdArgs := businessArgs
144		if cmd == "help" || cmd == "-h" || cmd == "--help" {
145			fmt.Fprint(stdout, usageText)
146			return 0
147		}
148	
149		// 最终路径确定之后才打开台账：被后续 -f 覆盖掉的旧路径与默认文件
150		// 即使损坏或不可读，也不会影响对有效目标文件的操作。
151		l, err := calibrate.Open(opts.file)
152		if err != nil {
153			fmt.Fprintln(stderr, "打开台账失败：", err)
154			return 2
155		}
156	
157		switch cmd {
158		case "register":
159			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
160		case "status":
161			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
162		case "cert":
163			return cmdCert(l, cmdArgs, opts, stdout, stderr)
164		case "use":
165			return cmdUse(l, cmdArgs, opts, stdout, stderr)
166		case "review":
167			return cmdReview(l, cmdArgs, opts, stdout, stderr)
168		case "list":
169			return cmdList(l, cmdArgs, opts, stdout, stderr)
170		case "plan":
171			return cmdPlan(l, cmdArgs, opts, stdout, stderr)
172		case "reschedule":
173			return cmdReschedule(l, cmdArgs, opts, stdout, stderr)
174		case "cancel":
175			return cmdCancel(l, cmdArgs, opts, stdout, stderr)
176		case "complete":
177			return cmdComplete(l, cmdArgs, opts, stdout, stderr)
178		case "todos":
179			return cmdTodos(l, cmdArgs, opts, stdout, stderr)
180		default:
181			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
182			return 2
183		}
184	}
185	
186	// newFlagSet 构造子命令自己的标志集。台账文件与 --json 已在打开台账前
187	// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
188	// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
189	func newFlagSet(name string, opts *options) *flag.FlagSet {
190		fs := flag.NewFlagSet(name, flag.ContinueOnError)
191		fs.SetOutput(io.Discard)
192		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
193		return fs
194	}
195	
196	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
197		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
198		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
199			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
200			return 0, false
201		}
202		return v, true
203	}
204	
205	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
206		if opts.asJSON {
207			raw, err := json.MarshalIndent(v, "", "  ")
208			if err != nil {
209				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
210				return 2
211			}
212			fmt.Fprintln(stdout, string(raw))
213			return 0
214		}
215		fmt.Fprint(stdout, human)
216		return 0
217	}
218	
219	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
220	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
221		if opts.asJSON {
222			raw, _ := json.MarshalIndent(rejected, "", "  ")
223			fmt.Fprintln(stdout, string(raw))
224		}
225		fmt.Fprintln(stderr, "已拒绝：", err)
226		return 1
227	}
228	
229	func failIO(stderr io.Writer, err error) int {
230		fmt.Fprintln(stderr, "操作失败：", err)
231		return 2
232	}
