289		// 先录入较晚（合格）证书，再补录更早的超差证书：补录只增加历史，
290		// 最近证书仍按校准日期取较晚的一张。
291		mustAddCert(t, l, cert("C-NEW", "2026-09-01", 0.1))
292		mustAddCert(t, l, cert("C-OLD", "2026-01-01", 5))
293		latest := l.LatestCertificate("M-1")
294		if latest.Number != "C-NEW" {
295			t.Fatalf("最近证书应按校准日期确定，得到 %s", latest.Number)
296		}
297		if n := len(l.certificatesOf("M-1")); n != 2 {
298			t.Fatalf("补录较早证书应增加历史，共 %d 张", n)
299		}
300	
301		// 同一器具同一天不接受两张不同编号的证书，拒绝时保留原记录。
302		n := len(l.data.Certificates)
303		_, _, err := l.AddCertificate(cert("C-DUP", "2026-09-01", 0.2))
304		if !IsValidation(err) || !strings.Contains(err.Error(), "同一天") {
305			t.Fatalf("同日不同号应被拒绝，得到 %v", err)
306		}
307		if len(l.data.Certificates) != n || l.findCertificate("C-DUP") != nil {
308			t.Fatal("同日拒绝不应留下任何记录")
309		}
310	
311		// 最近证书超差或到期时，不得回退到更早的合格证书。
312		clock2 := &fakeClock{t: mustDate(t, "2026-10-02")}
313		l2 := newTestLedger(t, clock2)
314		mustRegister(t, l2, "M-1", "万用表", 0.5)
315		mustAddCert(t, l2, cert("C-BAD", "2026-09-01", 5))    // 最近，超差
316		mustAddCert(t, l2, cert("C-GOOD", "2026-01-01", 0.0)) // 更早，合格
317		_ = l2.SetStatus("M-1", StatusInUse)
318		d, _ := l2.RequestUse("M-1")
319		if d.Allowed || !containsReason(d.Reasons, "超差") {
320			t.Fatalf("最近证书超差不得回退到更早的合格证书，得到 %v", d.Reasons)
321		}
322	}
